function run_case(name, fn)
global vlog_text
vlog_text = '';
try
    fprintf('CHK|%s|%s|exact\n', name, clean(fn()));
catch err
    fprintf('CHK|%s|ERR %s|exact\n', name, clean(err.message));
end
end

function s = clean(s)
if isnumeric(s) || islogical(s)
    s = mat2str(s);
end
s = char(s);
s = strrep(s, char(13), '');
s = strrep(s, char(10), ' ');
s = strrep(s, '|', '/');
end

function s = show(x)
% class, size and contents as text; a large array by its first two elements, its last and its sum.
sz = mat2str(size(x));
if isa(x, 'dictionary')
    ks = keys(x);
    parts = cell(1, numel(ks));
    for k = 1:numel(ks)
        parts{k} = sprintf('%s=%s', show(ks(k)), show(x(ks(k))));
    end
    s = sprintf('dictionary %d {%s}', numEntries(x), strjoin(parts, ' '));
elseif isa(x, 'ValueBox')
    s = sprintf('ValueBox p=%s', show(x.p));
elseif isstruct(x)
    if isscalar(x)
        fn = fieldnames(x);
        parts = cell(1, numel(fn));
        for k = 1:numel(fn)
            parts{k} = sprintf('%s=%s', fn{k}, show(x.(fn{k})));
        end
        s = sprintf('struct %s {%s}', sz, strjoin(parts, ' '));
    else
        fn = strjoin(fieldnames(x)', ',');
        if numel(x) <= 8
            parts = arrayfun(@(e) show_fields(e), x, 'UniformOutput', false);
            s = sprintf('struct %s [%s] {%s}', sz, fn, strjoin(parts(:)', ' '));
        else
            s = sprintf('struct %s [%s] {%s %s .. %s}', sz, fn, show_fields(x(1)), show_fields(x(2)), show_fields(x(end)));
        end
    end
elseif iscell(x)
    if numel(x) <= 8
        parts = cellfun(@show, x, 'UniformOutput', false);
        s = sprintf('cell %s {%s}', sz, strjoin(parts(:)', ' '));
    else
        s = sprintf('cell %s {%s %s .. %s}', sz, show(x{1}), show(x{2}), show(x{end}));
    end
elseif isstring(x)
    if numel(x) <= 8
        s = sprintf('string %s {%s}', sz, strjoin(cellstr(x(:)'), ' '));
    else
        s = sprintf('string %s {%s %s .. %s}', sz, x(1), x(2), x(end));
    end
elseif ischar(x)
    if numel(x) <= 16
        s = sprintf('char %s {%s}', sz, x(:)');
    else
        s = sprintf('char %s {%s%s..%s}', sz, x(1), x(2), x(end));
    end
elseif islogical(x)
    if numel(x) <= 8
        s = sprintf('logical %s %s', sz, mat2str(x));
    else
        d = double(x(:));
        s = sprintf('logical %s [%s %s .. %s] sum=%s', sz, mat2str(d(1)), mat2str(d(2)), mat2str(d(end)), mat2str(sum(d)));
    end
elseif isnumeric(x) && ~isreal(x)
    % real and imaginary planes apart: mat2str's spelling of a complex array is its own line (#61)
    if numel(x) <= 8
        s = sprintf('%s %s re=%s im=%s', class(x), sz, mat2str(double(real(x))), mat2str(double(imag(x))));
    else
        d = double(real(x(:))); e = double(imag(x(:)));
        s = sprintf('%s %s re=[%s %s .. %s] sum=%s im=[%s %s .. %s] sum=%s', class(x), sz, ...
            mat2str(d(1)), mat2str(d(2)), mat2str(d(end)), mat2str(sum(d)), ...
            mat2str(e(1)), mat2str(e(2)), mat2str(e(end)), mat2str(sum(e)));
    end
elseif isnumeric(x)
    if numel(x) <= 8
        s = sprintf('%s %s %s', class(x), sz, mat2str(double(x)));
    else
        d = double(x(:));
        s = sprintf('%s %s [%s %s .. %s] sum=%s', class(x), sz, mat2str(d(1)), mat2str(d(2)), mat2str(d(end)), mat2str(sum(d)));
    end
else
    s = sprintf('%s %s', class(x), sz);
end
end

function s = show_fields(e)
fn = fieldnames(e);
parts = cell(1, numel(fn));
for k = 1:numel(fn)
    parts{k} = show(e.(fn{k}));
end
s = strjoin(parts, ',');
end

function x = apply_in_callee(x, form)
switch form
    case 'elem:real'
        x(2) = 9;
    case 'elem2d:real'
        x(1, 2) = 9;
    case 'mask:real'
        m = false(size(x)); m(2) = true; x(m) = 9;
    case 'colon:real'
        x(:) = 9;
    case 'grow:real'
        x(end + 1) = 9;
    case 'delete:real'
        x(2) = [];
    case 'loop:real'
        for k = 1:2, x(k) = 9; end
    case 'complexify:real'
        x(2) = 1i;
    case 'charify:real'
        x(2) = 'a';
    case 'elem:complex'
        x(2) = 9;
    case 'elem2d:complex'
        x(1, 2) = 9;
    case 'mask:complex'
        m = false(size(x)); m(2) = true; x(m) = 9;
    case 'colon:complex'
        x(:) = 9;
    case 'grow:complex'
        x(end + 1) = 9;
    case 'delete:complex'
        x(2) = [];
    case 'loop:complex'
        for k = 1:2, x(k) = 9; end
    case 'elem:single'
        x(2) = 9;
    case 'elem2d:single'
        x(1, 2) = 9;
    case 'mask:single'
        m = false(size(x)); m(2) = true; x(m) = 9;
    case 'colon:single'
        x(:) = 9;
    case 'grow:single'
        x(end + 1) = 9;
    case 'delete:single'
        x(2) = [];
    case 'loop:single'
        for k = 1:2, x(k) = 9; end
    case 'complexify:single'
        x(2) = 1i;
    case 'elem:int32'
        x(2) = 9;
    case 'elem2d:int32'
        x(1, 2) = 9;
    case 'mask:int32'
        m = false(size(x)); m(2) = true; x(m) = 9;
    case 'colon:int32'
        x(:) = 9;
    case 'grow:int32'
        x(end + 1) = 9;
    case 'delete:int32'
        x(2) = [];
    case 'loop:int32'
        for k = 1:2, x(k) = 9; end
    case 'elem:logical'
        x(2) = false;
    case 'mask:logical'
        m = false(size(x)); m(2) = true; x(m) = false;
    case 'colon:logical'
        x(:) = false;
    case 'grow:logical'
        x(end + 1) = true;
    case 'delete:logical'
        x(2) = [];
    case 'numify:logical'
        x(2) = 9;
    case 'loop:logical'
        for k = 1:2, x(k) = false; end
    case 'elem:char'
        x(2) = 'z';
    case 'colon:char'
        x(:) = 'z';
    case 'grow:char'
        x(end + 1) = 'z';
    case 'delete:char'
        x(2) = [];
    case 'elem:string'
        x(2) = "z";
    case 'grow:string'
        x(end + 1) = "z";
    case 'delete:string'
        x(2) = [];
    case 'bracechar:string'
        x{2}(1) = 'Q';
    case 'brace:cell'
        x{2} = 9;
    case 'bracein:cell'
        x{2}(1) = 9;
    case 'paren:cell'
        x(2) = {9};
    case 'delete:cell'
        x(2) = [];
    case 'grow:cell'
        x{end + 1} = 9;
    case 'elemfield:structarr'
        x(2).f = 9;
    case 'elemfieldin:structarr'
        x(2).f(1) = 9;
    case 'delete:structarr'
        x(2) = [];
    case 'grow:structarr'
        x(end + 1).f = 9;
    case 'newfield:structarr'
        x(2).g = 9;
    case 'field:struct'
        x.f = 9;
    case 'fieldin:struct'
        x.f(2) = 9;
    case 'newfield:struct'
        x.g = 9;
    case 'prop:object'
        x.p = 9;
    case 'propin:object'
        x.p(2) = 9;
    case 'key:dict'
        x(2) = 9;
    case 'newkey:dict'
        x(5 + 1) = 9;
    case 'remove:dict'
        x(2) = [];
end
end

